package com.fakelegacy.order.pricing;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.List;

import org.aspectj.lang.ProceedingJoinPoint;
import org.aspectj.lang.annotation.Around;
import org.aspectj.lang.annotation.Aspect;
import org.springframework.stereotype.Component;

/** Caps cumulated discounts on non-sale lines at 30% of their undiscounted amount; only the promo is reduced. */
@Aspect
@Component
public class DiscountCapAspect {

    @Around("execution(* com.fakelegacy.order.pricing.PriceCalculator.close(..))")
    public Object capDiscounts(ProceedingJoinPoint pjp) throws Throwable {
        PricingResult result = (PricingResult) pjp.proceed();

        BigDecimal base = BigDecimal.ZERO;
        BigDecimal discounts = BigDecimal.ZERO;
        BigDecimal promoTotal = BigDecimal.ZERO;
        for (LineDraft l : result.getLines()) {
            if (l.isOnSale()) {
                continue;
            }
            base = base.add(l.gross());
            discounts = discounts.add(l.totalDiscount());
            promoTotal = promoTotal.add(l.getDiscountPromo());
        }
        BigDecimal cap = base.multiply(PricingConstants.DISCOUNT_CAP_RATE).setScale(2, RoundingMode.DOWN);
        if (discounts.compareTo(cap) <= 0) {
            return result;
        }

        BigDecimal allowedPromo = cap.subtract(discounts.subtract(promoTotal)).max(BigDecimal.ZERO);
        List<LineDraft> promoLines = new ArrayList<>();
        for (LineDraft l : result.getLines()) {
            if (l.getDiscountPromo().signum() > 0) {
                promoLines.add(l);
            }
        }
        BigDecimal assigned = BigDecimal.ZERO;
        for (int i = 0; i < promoLines.size(); i++) {
            LineDraft l = promoLines.get(i);
            BigDecimal reduced;
            if (i == promoLines.size() - 1) {
                reduced = allowedPromo.subtract(assigned).max(BigDecimal.ZERO);
            } else {
                reduced = l.getDiscountPromo().multiply(allowedPromo).divide(promoTotal, 2, RoundingMode.DOWN);
            }
            reduced = reduced.min(l.getDiscountPromo());
            l.setDiscountPromo(reduced);
            assigned = assigned.add(reduced);
        }
        result.setCapApplied(true);
        result.recomputeTotals();
        return result;
    }
}
